<script setup lang="ts">
import {ElMessage} from 'element-plus'
import {getNotificationDeliveries,type NotificationDelivery} from '@/api/notifications'
import {errorMessage} from '@/api/asset-ops'
import TableSortHeader from '@/components/TableSortHeader.vue'
import TablePager from '@/components/TablePager.vue'
import {useServerTable} from '@/features/table/useServerTable'
import {useColumnWidths} from '@/features/table/useColumnWidths'
import '@/styles/asset-ops.css'
const {rows:deliveries,total,page,pageSize,loading:historyLoading,failed,search,query,tableRef,sortBy,onSortChange,reload:history,clearSearch}=useServerTable<NotificationDelivery>(params=>getNotificationDeliveries(params.page,params),20,e=>ElMessage.error(errorMessage(e)))
const {columnWidths,resizeColumn}=useColumnWidths({createdAt:185,channel:120,source:100,summary:210,status:125,errorMessage:230})
const formatTime=(v:string)=>new Date(v).toLocaleString('zh-CN',{hour12:false})
</script>
<template><div class="asset-ops"><div class="ops-heading"><div><h1>通知发送记录</h1><p>统一追踪告警、审批邮件和渠道测试的发送结果；通道接收成功不代表收件人已阅读。</p></div></div>    <el-card shadow="never" >
      <template #header><div class="ops-toolbar between"><span class="ops-muted">按渠道追踪告警、审批和测试消息的处理结果</span><el-button :loading="historyLoading" @click="history">刷新记录</el-button></div></template>
      <el-input v-model="search" clearable aria-label="搜索通知发送记录" placeholder="搜索摘要、失败原因、收件人或消息编号" style="max-width:420px;margin-bottom:12px"/><el-alert v-if="failed" title="加载失败，请重试；当前行可能不是最新查询结果" type="error" :closable="false"/><el-table ref="tableRef" @sort-change="onSortChange" :data="deliveries" v-loading="historyLoading"><el-table-column label="发送时间" prop="createdAt" :width="columnWidths['createdAt']" sortable="custom"><template #header><TableSortHeader label="发送时间" :width="columnWidths['createdAt']" @sort="sortBy('createdAt')" @resize="resizeColumn('createdAt',$event)"/></template><template #default="{row}">{{ formatTime(row.createdAt) }}</template></el-table-column><el-table-column label="渠道" prop="channel" :width="columnWidths['channel']" sortable="custom"><template #header><TableSortHeader label="渠道" :width="columnWidths['channel']" @sort="sortBy('channel')" @resize="resizeColumn('channel',$event)"/></template><template #default="{row}">{{ row.channel === 'EMAIL' ? '邮件' : '企业微信' }}</template></el-table-column><el-table-column label="来源" prop="source" :width="columnWidths['source']" sortable="custom"><template #header><TableSortHeader label="来源" :width="columnWidths['source']" @sort="sortBy('source')" @resize="resizeColumn('source',$event)"/></template><template #default="{row}">{{ row.test ? '渠道测试' : row.summary?.startsWith('待审批') ? '审批通知' : '告警通知' }}</template></el-table-column><el-table-column label="收件邮箱 / 消息编号" min-width="240"><template #default="{row}"><span>{{row.recipients?.join('；')||'—'}}</span><small v-if="row.messageId" class="ops-block ops-mono">{{row.messageId}}</small></template></el-table-column><el-table-column label="通知摘要" prop="summary" :width="columnWidths['summary']" sortable="custom"><template #header><TableSortHeader label="通知摘要" :width="columnWidths['summary']" @sort="sortBy('summary')" @resize="resizeColumn('summary',$event)"/></template></el-table-column><el-table-column label="结果" prop="status" :width="columnWidths['status']" sortable="custom"><template #header><TableSortHeader label="结果" :width="columnWidths['status']" @sort="sortBy('status')" @resize="resizeColumn('status',$event)"/></template><template #default="{row}"><el-tag :type="row.status === 'SUCCESS' ? 'success' : 'danger'" effect="light">{{ row.status === 'SUCCESS' ? '通道已接收' : '发送失败' }}</el-tag></template></el-table-column><el-table-column label="失败原因" prop="errorMessage" :width="columnWidths['errorMessage']" sortable="custom"><template #header><TableSortHeader label="失败原因" :width="columnWidths['errorMessage']" @sort="sortBy('errorMessage')" @resize="resizeColumn('errorMessage',$event)"/></template></el-table-column><template #empty><el-empty :description="failed?'加载失败':query?'没有匹配记录':'暂无发送记录'"><el-button v-if="query" @click="clearSearch">清除筛选</el-button></el-empty></template></el-table>
      <TablePager v-model:page="page" v-model:page-size="pageSize" :total="total" label="通知发送记录"/>
    </el-card></div></template>
